import unittest
from error_lines import *
class ErrorLines(unittest.TestCase):
    def test_line_anchors_without_cross_line_dot(self):
        rows=[('INFO: up\nERROR: disk full\nERROR: stale key\nDONE',['disk full','stale key']),('ERROR: first\nnext line',['first']),('INFO: ERROR: embedded\nERROR: final',['final']),('ERROR: \nERROR: oak',['oak']),('ERROR: one\n',['one']),('nothing',[]),('',[])]
        for text,expected in rows:
            with self.subTest(text=text):
                self.assertEqual(error_messages(text),expected)

if __name__ == '__main__':
    unittest.main()

